请对以下 case 进行三维加权评分。

=== case_id ===
Case-29-elderly-care-006

=== 用户原始指令 (query.txt) ===
搞个步数会变的卡片吧点一下能跳进应用看到红色提示那种

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "搞个步数会变的卡片吧点一下能跳进应用看到红色提示那种",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "care": {
        "title": {
          "type": "string",
          "description": "步数卡片标题",
          "sampleValue": "今日步数"
        },
        "stepsText": {
          "type": "string",
          "description": "当前步数展示文本，会随数据更新变化",
          "sampleValue": "4,320"
        },
        "unitText": {
          "type": "string",
          "description": "步数单位文本",
          "sampleValue": "步"
        },
        "alertText": {
          "type": "string",
          "description": "红色提醒状态文案",
          "sampleValue": "步数偏低"
        },
        "hintText": {
          "type": "string",
          "description": "点击进入应用查看详情的短提示",
          "sampleValue": "查看"
        }
      }
    }
  },
  "assetCandidates": []
}

